// Use the Bundle generated by the actual CLI without reading compiler-private state.
func streamCallbackBundle(t *testing.T) openapi.Bundle { t.Helper(); return apidoc.Bundle() }

// Validate SSE and NDJSON over real HTTP and compare status, headers, and body before and after mounting.
func TestStreamCallbacksWire(t *testing.T) {
	bundle := streamCallbackBundle(t)
	for _, sample := range []struct {
		name        string
		handler     gin.HandlerFunc
		status      int
		media, body string
		empty       bool
	}{
		{"once", StreamOnce, 202, "text/event-stream", "event:one\ndata:hello\n\n", false},
		{"repeated", StreamRepeated, 200, "text/event-stream", "event:count\ndata:1\n\nevent:count\ndata:2\n\nevent:count\ndata:3\n\n", false},
		{"factory", StreamFactory, 200, "text/event-stream", "event:factory\ndata:captured\n\n", false},
		{"empty", StreamEmpty, 202, "text/event-stream", "", true},
		{"ndjson", StreamNDJSON, 200, "application/x-ndjson", "{\"Name\":\"Ada\",\"Count\":0}\n{\"Name\":\"Ada\",\"Count\":1}\n{\"Name\":\"Ada\",\"Count\":2}\n", false},
		{"captured-encoder", StreamCapturedEncoder, 200, "application/x-ndjson", "{\"Name\":\"outside\",\"Count\":4}\n", false},
	} {
		for _, method := range []string{"GET", "HEAD", "POST"} {
			t.Run(sample.name+"/"+method, func(t *testing.T) {
				before, after := gin.New(), gin.New()
				before.Handle(method, "/stream", sample.handler)
				after.Handle(method, "/stream", sample.handler)
				doc, err := ginswagger.Mount(after, bundle, ginswagger.Config{OpenAPI: openapi.Config{Title: "Callbacks", Version: "1"}})
				if err != nil {
					t.Fatal(err)
				}
				var bodies [][]byte
				var headers []http.Header
				for _, engine := range []*gin.Engine{before, after} {
					server := httptest.NewServer(engine)
					request, _ := http.NewRequest(method, server.URL+"/stream", nil)
					response, err := server.Client().Do(request)
					if err != nil {
						server.Close()
						t.Fatal(err)
					}
					raw, err := io.ReadAll(response.Body)
					response.Body.Close()
					server.Close()
					if err != nil {
						t.Fatal(err)
					}
					if response.StatusCode != sample.status || !strings.HasPrefix(response.Header.Get("Content-Type"), sample.media) {
						t.Fatalf("wrong status/media: %d %v", response.StatusCode, response.Header)
					}
					response.Header.Del("Date")
					bodies = append(bodies, raw)
					headers = append(headers, response.Header)
				}
				expected := sample.body
				if method == "HEAD" {
					expected = ""
				}
				if string(bodies[0]) != expected || !bytes.Equal(bodies[0], bodies[1]) || !reflect.DeepEqual(headers[0], headers[1]) {
					t.Fatalf("changed or unexpected wire response: %q %q", bodies[0], bodies[1])
				}
				var model spec.OpenAPI
				if err := json.Unmarshal(doc.JSON(), &model); err != nil {
					t.Fatal(err)
				}
				response := httpOperation(model.Paths["/stream"], method).Responses[strconv.Itoa(sample.status)].Value
				if response == nil {
					t.Fatal("missing actual status")
				}
				if method == "HEAD" || sample.empty {
					if len(response.Content) != 0 {
						t.Fatal("empty stream retained content")
					}
					return
				}
				pointer := "/paths/~1stream/" + strings.ToLower(method) + "/responses/" + strconv.Itoa(sample.status) + "/content/" + strings.ReplaceAll(sample.media, "/", "~1") + "/itemSchema"
				validator, err := contracttest.Compile(doc.JSON(), pointer, contracttest.Options{AssertContent: true})
				if err != nil {
					t.Fatal(err)
				}
				if sample.media == "text/event-stream" {
					err = validator.SSE(bytes.NewReader(bodies[1]), contracttest.Limits{})
					if validator.Value(map[string]any{"data": 3}) == nil {
						t.Fatal("data lost its string constraint")
					}
				} else {
					err = validator.NDJSON(bytes.NewReader(bodies[1]), contracttest.Limits{})
					if validator.JSON([]byte(`{"Name":7,"Count":"bad"}`)) == nil {
						t.Fatal("JSON DTO constraints were lost")
					}
				}
				if err != nil {
					t.Fatal(err)
				}
			})
		}
	}
}

// Unresolved callbacks, invalid line framing, and late media headers must block selected routes.
func TestStreamCallbacksDiagnostics(t *testing.T) {
	bundle := streamCallbackBundle(t)
	for _, handler := range []gin.HandlerFunc{StreamMissingMedia, StreamIndented, StreamNil, StreamLateMedia, StreamUnknownWriter} {
		engine := gin.New()
		engine.GET("/bad", handler)
		if _, err := ginswagger.Build(engine, bundle, ginswagger.Config{OpenAPI: openapi.Config{Title: "Bad", Version: "1"}}); err == nil {
			t.Fatal("unresolved callback accepted")
		}
	}
}

// A stable long-lived stream generates a native contract and its handler terminates promptly after the real client closes.
func TestStreamCallbackCancellation(t *testing.T) {
	bundle := streamCallbackBundle(t)
	engine := gin.New()
	done := make(chan struct{})
	engine.Use(func(c *gin.Context) { c.Next(); close(done) })
	engine.GET("/stream", StreamUntilClosed)
	doc, err := ginswagger.Build(engine, bundle, ginswagger.Config{OpenAPI: openapi.Config{Title: "Long-lived stream", Version: "1"}})
	if err != nil {
		t.Fatal(err)
	}
	server := httptest.NewServer(engine)
	defer server.Close()
	client := server.Client()
	client.Timeout = 5 * time.Second
	response, err := client.Get(server.URL + "/stream")
	if err != nil {
		t.Fatal(err)
	}
	reader := bufio.NewReader(response.Body)
	var raw strings.Builder
	for i := 0; i < 3; i++ {
		line, err := reader.ReadString('\n')
		if err != nil {
			response.Body.Close()
			t.Fatal(err)
		}
		raw.WriteString(line)
	}
	response.Body.Close()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		server.CloseClientConnections()
		t.Fatal("stream did not observe client closure")
	}
	if raw.String() != "event:tick\ndata:ready\n\n" {
		t.Fatalf("unexpected frame: %q", raw.String())
	}
	validator, err := contracttest.Compile(doc.JSON(), "/paths/~1stream/get/responses/200/content/text~1event-stream/itemSchema", contracttest.Options{AssertContent: true})
	if err != nil {
		t.Fatal(err)
	}
	if err := validator.SSE(strings.NewReader(raw.String()), contracttest.Limits{}); err != nil {
		t.Fatal(err)
	}
	if validator.Value(map[string]any{"event": "tick", "data": "wrong"}) == nil {
		t.Fatal("stable event content was lost")
	}
}
